create table if not exists public.location_quality_reviews (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, status text not null default 'pending' check (status in ('pending','approved','merged','rejected')), canonical_location_id uuid references public.locations(id) on delete set null, normalized_name text, normalized_address text, candidate_key text, evidence jsonb not null default '{}'::jsonb, reviewed_by uuid references auth.users(id) on delete set null, reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists location_quality_reviews_status_idx on public.location_quality_reviews(status); create index if not exists location_quality_reviews_location_idx on public.location_quality_reviews(location_id); create index if not exists location_quality_reviews_candidate_idx on public.location_quality_reviews(candidate_key); alter table public.location_quality_reviews enable row level security; create policy "admins manage location quality reviews" on public.location_quality_reviews for all using (exists (select 1 from public.profiles p where p.id = auth.uid() and (p.role = 'admin' or p.is_admin = true))) with check (exists (select 1 from public.profiles p where p.id = auth.uid() and (p.role = 'admin' or p.is_admin = true)));
